const setRequestStatus = `-- name: SetRequestStatus :execrows
UPDATE procurement.requests SET status = $1, updated_at = $2
WHERE id = $3 AND buyer_id = $4 AND status = $5
`

type SetRequestStatusParams struct {
	Status     string
	Now        time.Time
	ID         uuid.UUID
	BuyerID    *int64
	FromStatus string
}

// 條件式轉移（S2：requests 沒有 version）：只有目前狀態是 from_status 時才改。
func (q *Queries) SetRequestStatus(ctx context.Context, arg SetRequestStatusParams) (int64, error) {
	result, err := q.db.Exec(ctx, setRequestStatus,
		arg.Status,
		arg.Now,
		arg.ID,
		arg.BuyerID,
		arg.FromStatus,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const setRequestStatusFromAny = `-- name: SetRequestStatusFromAny :execrows
UPDATE procurement.requests SET status = $1, updated_at = $2
WHERE id = $3 AND buyer_id = $4 AND status = ANY($5::text[])
`

type SetRequestStatusFromAnyParams struct {
	ToStatus     string
	Now          time.Time
	ID           uuid.UUID
	BuyerID      *int64
	FromStatuses []string
}

// 條件式轉移到 to：目前狀態在 from_statuses 之內才改（搜尋成功時來源可以是 REQUIREMENT_READY 或 MATCHING）。
func (q *Queries) SetRequestStatusFromAny(ctx context.Context, arg SetRequestStatusFromAnyParams) (int64, error) {
	result, err := q.db.Exec(ctx, setRequestStatusFromAny,
		arg.ToStatus,
		arg.Now,
		arg.ID,
		arg.BuyerID,
		arg.FromStatuses,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const softDeleteConversation = `-- name: SoftDeleteConversation :execrows
UPDATE procurement.conversations SET deleted_at = $1, updated_at = $1
WHERE id = $2 AND buyer_id = $3 AND deleted_at IS NULL
`

type SoftDeleteConversationParams struct {
	Now     *time.Time
	ID      uuid.UUID
	BuyerID int64
}

// 目標狀態的方法（S4）：已刪除的不再更新時間，重送結果相同。
func (q *Queries) SoftDeleteConversation(ctx context.Context, arg SoftDeleteConversationParams) (int64, error) {
	result, err := q.db.Exec(ctx, softDeleteConversation, arg.Now, arg.ID, arg.BuyerID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const supersedeActiveRevision = `-- name: SupersedeActiveRevision :execrows
UPDATE procurement.request_revisions v SET status = 'SUPERSEDED'
WHERE v.request_id = $1 AND v.status = 'ACTIVE'
  AND EXISTS (SELECT 1 FROM procurement.requests r WHERE r.id = v.request_id AND r.buyer_id = $2)
`

type SupersedeActiveRevisionParams struct {
	RequestID uuid.UUID
	BuyerID   *int64
}

// 新版本寫入前先把現行版本轉成 SUPERSEDED（partial unique 擋雙頭）。
func (q *Queries) SupersedeActiveRevision(ctx context.Context, arg SupersedeActiveRevisionParams) (int64, error) {
	result, err := q.db.Exec(ctx, supersedeActiveRevision, arg.RequestID, arg.BuyerID)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
